static long mod = 1000000007;
static long mod1 = 998244353;

/*****************************************Solution Begins***********************************************/
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long n, m, l, r;
    cin >> n >> m >> l >> r;
    long d = r - l + 1;
    long a = d / 2;
    long b = d - a;
    long long nm = (long long)n * m;
    mod = mod1;

    auto modulo = [](long long a, long long b, long long c) -> long long {
        long long x = 1;
        long long y = a % c;
        while (b > 0) {
            if (b % 2 == 1)
                x = (x * y) % c;
            y = (y * y) % c;
            b /= 2;
        }
        return x % c;
    };

    long long ans = ( (modulo((long long)a + b, nm, mod) + modulo(abs(a - b), nm, mod)) % mod );
    ans = (ans * modulo(2, mod - 2, mod)) % mod;
    if (nm % 2 == 1) {
        ans = modulo(d, nm, mod);
    }
    cout << ans << "\n";

    return 0;
}
